import com.fasterxml.jackson.dataformat.xml.XmlMapper;
import java.math.BigDecimal;

public class TransferFundsRequestMapper {

    private static final XmlMapper XML_MAPPER = new XmlMapper();

    public TransferFundsRequest toBusinessInput(String xml) throws Exception {
        TransferFundsRequestXml wire = XML_MAPPER.readValue(xml, TransferFundsRequestXml.class);
        return toBusinessInput(wire);
    }

    public TransferFundsRequest toBusinessInput(TransferFundsRequestXml wire) {
        TransferFundsRequest req = new TransferFundsRequest();

        if (wire != null && wire.transferFunds != null) {
            TransferFundsXml tf = wire.transferFunds;
            req.setSourceAccount(unformatSourceAccount(tf.sourceAccount));
            req.setTargetAccount(unformatTargetAccount(tf.targetAccount));
            req.setAmount(unformatAmount(tf.amount));
            req.setCurrency(unformatCurrency(tf.currency));
            req.setSessionToken(unformatSessionToken(tf.sessionToken));
            req.setTransferReference(unformatTransferReference(tf.transferReference, tf.transferReferenceNil));
            req.setScheduledDate(unformatScheduledDate(tf.scheduledDate, tf.scheduledDateNil));
        }

        return req;
    }

    private String unformatSourceAccount(String value) {
        if (value == null) return null;
        // Reverse CCPadding (padChar='0', length=10, padLeft=true) -> remove leading zeros
        return value.replaceFirst("^0+", "");
    }

    private String unformatTargetAccount(String value) {
        if (value == null) return null;
        // Reverse CCPadding (padChar='0', length=10, padLeft=true) -> remove leading zeros
        return value.replaceFirst("^0+", "");
    }

    private BigDecimal unformatAmount(String value) {
        if (value == null || value.isBlank()) return null;
        String clean = value.replace(",", "");
        return new BigDecimal(clean);
    }

    private String unformatCurrency(String value) {
        if (value == null) return null;
        // Reverse CCPadding (padChar=' ', length=3, padLeft=true) -> remove leading spaces
        return value.replaceFirst("^ +", "");
    }

    private String unformatSessionToken(String value) {
        // MaskLogDecorator unformat is a pass-through
        return value;
    }

    private String unformatTransferReference(String value, Boolean nil) {
        if (Boolean.TRUE.equals(nil) || value == null) {
            return null;
        }
        // Reverse NilDecorator: if not nil, return value (or empty string if nil handled as null)
        return value;
    }

    private String unformatScheduledDate(String value, Boolean nil) {
        if (Boolean.TRUE.equals(nil) || value == null) {
            return null;
        }
        return value;
    }
}

